mapper.select:
SELECT id, info_hash, torrent_bencode, metainfo_sha256,
       piece_length, piece_count, total_bytes, created_at
FROM torrent_native_metadata WHERE info_hash = #{infoHash}

SELECT * FROM torrent_native_task
WHERE user_id = #{userId} AND deleted = 0
ORDER BY created_at DESC, id DESC LIMIT #{limit} OFFSET #{offset}

SELECT * FROM torrent_native_task
WHERE deleted = 0 AND status = 'RUNNING'
ORDER BY id ASC LIMIT #{limit}

mapper.update:
UPDATE torrent_native_task
SET verified_selected_bytes=#{verifiedBytes},
    downloaded_wire_bytes=#{wireBytes},
    status=CASE WHEN #{completed} THEN 'COMPLETED' ELSE 'RUNNING' END,
    revision=revision+1,updated_at=CURRENT_TIMESTAMP
WHERE task_uuid=#{taskUuid} AND user_id=#{userId} AND deleted=0
  AND status='RUNNING' AND revision=#{expectedRevision}
  AND execution_epoch=#{epoch} AND execution_instance_id=#{instanceId}
  AND verified_selected_bytes <= #{verifiedBytes}
  AND downloaded_wire_bytes <= #{wireBytes}
  AND selected_total_bytes >= #{verifiedBytes}

UPDATE torrent_native_task
SET verified_selected_bytes = #{verifiedSelectedBytes},
    downloaded_wire_bytes = #{downloadedWireBytes},
    status = CASE WHEN #{completed} THEN 'COMPLETED' ELSE 'RUNNING' END,
    completed_at = CASE WHEN #{completed} THEN CURRENT_TIMESTAMP ELSE completed_at END,
    revision = revision + 1, updated_at = CURRENT_TIMESTAMP
WHERE task_uuid = #{taskUuid} AND user_id = #{userId} AND deleted = 0
  AND status = 'RUNNING' AND revision = #{expectedRevision}
  AND execution_instance_id IS NULL
  AND verified_selected_bytes <= #{verifiedSelectedBytes}
  AND downloaded_wire_bytes <= #{downloadedWireBytes}
  AND selected_total_bytes >= #{verifiedSelectedBytes}
